/** Effects for menus and screens, magic, bells, drums, instruments, cartoons and board games. */

import type { Layer } from '../engine';
import { BELL_PARTS, CHIME_PARTS, GLASS_PARTS, GONG_PARTS, PATCHES, brush, chipHat, chipKick, chipSnare, clap, clave, conga, cowbell, cymbal, hat, kick, modal, ride, rim, shaker, snare, tambourine, timpani, tom, triangleHit, woodblock } from '../instruments';
import { MAJOR, PENTA, click, hit, hold, nz, ping, run, shift, swell, thump, type Family } from './core';

const at = (layers: Layer[], t: number, v = 1): Layer[] => shift(layers, t, v);
/** A chord: the same instrument on several notes (semitones above `f`). */
const chord = (patch: keyof typeof PATCHES, f: number, d: number, semis: number[], v = 0.6): Layer[] => semis.flatMap((s) => PATCHES[patch](f * 2 ** (s / 12), d, v));

